19: export function addBasketItem () {
20:   return async (req: Request, res: Response, next: NextFunction) => {
21:     const result = utils.parseJsonCustom((req as RequestWithRawBody).rawBody)
22:     const productIds = []
23:     const basketIds = []
24:     const quantities = []
25: 
26:     for (let i = 0; i < result.length; i++) {
27:       if (result[i].key === 'ProductId') {
28:         productIds.push(result[i].value)
29:       } else if (result[i].key === 'BasketId') {
30:         basketIds.push(result[i].value)
31:       } else if (result[i].key === 'quantity') {
32:         quantities.push(result[i].value)
33:       }
34:     }
